namespace ParkingSystem;
public partial class ReportValidation
{
 private UserSession? session; private ParkingService? service; internal CancellationToken ShellCancellation;
 private RoundedButton? validateButton; private IReadOnlyList<DepositRecord> rows=Array.Empty<DepositRecord>();
 public void Bind(UserSession s, ParkingService p){session=s;service=p;reportdateDarkDateTimePicker.Value=ParkingTime.Wib(DateTimeOffset.UtcNow).Date;approveButton.Visible=false;rejectButton.Visible=false;statusComboBox.Items.Clear();statusComboBox.Items.AddRange(new object[]{"All statuses","Pending","Matched","Need review"});statusComboBox.SelectedIndex=0;validateButton??=new RoundedButton{Text="Validasi setoran",AutoSize=true};validateButton.Click-=ValidateClick;validateButton.Click+=ValidateClick;if(!reviewnotePanel.Controls.Contains(validateButton))reviewnotePanel.Controls.Add(validateButton);searchButton.Text="Refresh";searchButton.Click-=SearchClick;searchButton.Click+=SearchClick;grid17.SelectionChanged-=RowChanged;grid17.SelectionChanged+=RowChanged;_ = RefreshAsync(ShellCancellation);}
 private void SetPastDate(){reportdateDarkDateTimePicker.Value=ParkingTime.Wib(DateTimeOffset.UtcNow).Date;}
 private void SearchClick(object? s,EventArgs e)=>_ = RefreshAsync(ShellCancellation);
 private async void ValidateClick(object? s,EventArgs e){if(session is null||service is null||grid17.CurrentRow is null||grid17.CurrentRow.Index<0||grid17.CurrentRow.Index>=rows.Count)return;var item=rows[grid17.CurrentRow.Index];if(item.Status!=DepositStatus.Pending){MessageBox.Show(this,"Laporan ini sudah divalidasi.");return;}if(MessageBox.Show(this,"Validasi setoran ini?","Konfirmasi",MessageBoxButtons.YesNo)==DialogResult.Yes)await UiOperations.RunAsync(this,validateButton,ShellCancellation,async()=>{await service.ValidateDepositAsync(session,item.Id,reviewnoteTextBox.Text,ShellCancellation);await RefreshAsync(ShellCancellation);});}
 private void RowChanged(object? s,EventArgs e){if(grid17.CurrentRow is not null&&grid17.CurrentRow.Index<rows.Count){var x=rows[grid17.CurrentRow.Index];reviewnoteTextBox.Text=x.Notes??"";if(validateButton is not null)validateButton.Enabled=x.Status==DepositStatus.Pending;}}
 public async Task RefreshAsync(CancellationToken ct){if(service is null||session is null)return;await UiOperations.RunAsync(this,searchButton,ct,async()=>{var st=statusComboBox.SelectedIndex switch{1=>DepositStatus.Pending,2=>DepositStatus.Matched,3=>DepositStatus.NeedReview,_=>(DepositStatus?)null};rows=await service.GetDepositsAsync(session,DateOnly.FromDateTime(reportdateDarkDateTimePicker.Value),st,ct);grid17.DataSource=rows.Select(x=>new{x.Id,Jukir=x.JukirName,Deposited=x.AmountDeposited,Expected=x.AmountExpected,Discrepancy=x.Discrepancy,Status=x.Status.ToString(),Admin=x.AdminName??"—",Notes=x.Notes??""}).ToList();});}
}